spec.setup_code:
var origin = new api.THREE.Vector3(0, 0, 0);
var arrowR = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 1, 0x2E7D32);
var arrowX = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 0.1, 0x4C72B0);
var arrowY = new api.THREE.ArrowHelper(new api.THREE.Vector3(0, 1, 0), origin, 0.1, 0xE8593C);
api.group.add(arrowR);
api.group.add(arrowX);
api.group.add(arrowY);
return {
  update: function(t) {
    var theta = (Math.sin(t * 0.005) * 0.5 + 0.5) * (Math.PI / 2);
    var R = 2;
    var Vx = R * Math.cos(theta), Vy = R * Math.sin(theta);
    arrowR.setDirection(new api.THREE.Vector3(Vx, Vy, 0).normalize());
    arrowR.setLength(R);
    arrowX.setLength(Math.max(Math.abs(Vx), 0.01));
    arrowY.setLength(Math.max(Math.abs(Vy), 0.01));
  }
};

return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    function arrow(x0, y0, x1, y1, color) {
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
      var ang = Math.atan2(y1 - y0, x1 - x0);
      var hs = 10;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x1 - hs * Math.cos(ang - Math.PI / 6), y1 - hs * Math.sin(ang - Math.PI / 6));
      ctx.lineTo(x1 - hs * Math.cos(ang + Math.PI / 6), y1 - hs * Math.sin(ang + Math.PI / 6));
      ctx.closePath();
      ctx.fill();
    }
    var scale = Math.min(W, H) * 0.02;
    var ox = W * 0.25, oy = H * 0.75;
    var R = 6;
    var theta = (Math.PI / 6) + (Math.sin(t * 0.01) * 0.5 + 0.5) * (Math.PI / 2 - Math.PI / 6);
    var Vx = R * Math.cos(theta) * scale;
    var Vy = R * Math.sin(theta) * scale;
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = '#4C72B0';
    ctx.beginPath();
    ctx.moveTo(ox, oy);
    ctx.lineTo(ox + Vx, oy);
    ctx.stroke();
    ctx.strokeStyle = '#E8593C';
    ctx.beginPath();
    ctx.moveTo(ox + Vx, oy);
    ctx.lineTo(ox + Vx, oy - Vy);
    ctx.stroke();
    ctx.setLineDash([]);
    arrow(ox, oy, ox + Vx, oy - Vy, '#2E7D32');
    ctx.fillStyle = '#333';
    ctx.font = '14px sans-serif';
    ctx.fillText('Vx = R cos(theta)', ox + Vx / 2 - 30, oy + 18);
    ctx.fillText('Vy = R sin(theta)', ox + Vx + 8, oy - Vy / 2);
    ctx.fillText('R', ox + Vx / 2, oy - Vy / 2 - 10);
  }
};
